        check(&s, mismatches);
    }
}

/// Tokens, then a Stats-like count, over every line; returns elapsed seconds and a checksum.
fn time_old(lines: &[String]) -> (f64, u64) {
    let start = Instant::now();
    let mut sum = 0u64;
    for line in lines {
        for t in old_token::tokenize(black_box(line)) {
            match t {
                Ok(old_token::Token::Key(s)) => sum += s.len() as u64,
                Ok(old_token::Token::Word(s)) => sum += 2 * s.len() as u64,
                Ok(old_token::Token::Timestamp(s)) => sum += 3 * s.len() as u64,
                Ok(_) => {}
                Err(_) => {
                    sum += 1;
                    break;
                }
            }
        }
    }
    (start.elapsed().as_secs_f64(), black_box(sum))
}

fn time_new(lines: &[String]) -> (f64, u64) {
    let start = Instant::now();
    let mut sum = 0u64;
    for line in lines {
        for t in new_token::tokenize(black_box(line)) {
            match t {
                Ok(new_token::Token::Key(s)) => sum += s.len() as u64,
                Ok(new_token::Token::Word(s)) => sum += 2 * s.len() as u64,
                Ok(new_token::Token::Timestamp(s)) => sum += 3 * s.len() as u64,
                Ok(_) => {}
                Err(_) => {
                    sum += 1;
                    break;
                }
            }
        }
    }
    (start.elapsed().as_secs_f64(), black_box(sum))
}

fn corpus(n: usize) -> Vec<String> {
    let mut rng = XorShift(0x1234_5678_9ABC_DEF1);
    let levels = ["info", "warn", "error", "debug"];
    (0..n)
        .map(|i| {
            let r = rng.next();
            let mut line = format!(
                "[2024-05-01T12:{:02}:{:02}Z] level={} msg=\"disk {}% full \\\"x\\\" \n\" user=ann{} retries= tag=a=b",
                i % 60,
                (i / 60) % 60,
                levels[(r % 4) as usize],
                r % 100,
                r % 1000
            );
            if r % 97 == 0 {
                line.push_str(" bad=\"oops");
            }
            if r % 13 == 0 {
                line.push_str(" stray words here\tand\tthere");
            }
            line
        })
        .collect()
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    let mut mismatches = 0u64;
    if mode == "verify" {
        let alphabet: Vec<char> = "[]\"=\ \tna\u{e9}".chars().collect();
        let n = exhaustive(&alphabet, 7, &mut mismatches);
        println!("exhaustive: {n} inputs over {} chars, mismatches so far {mismatches}", alphabet.len());
        random_cases(3_000_000, &mut mismatches);
        println!("random: 3000000 inputs, mismatches {mismatches}");
        if mismatches > 0 {
            std::process::exit(1);
        }
        println!("OK: old and new agree on every input");
    } else {
        let lines = corpus(1_000_000);
        let bytes: usize = lines.iter().map(|l| l.len()).sum();
        println!("corpus: {} lines, {} MB", lines.len(), bytes / 1_000_000);
        let (mut best_old, mut best_new) = (f64::MAX, f64::MAX);
        let (mut so, mut sn) = (0, 0);
        for round in 0..7 {
            let (o, a) = time_old(&lines);
            let (n, b) = time_new(&lines);
            assert_eq!(a, b);
            so = a;
            sn = b;
            if round > 0 {
                best_old = best_old.min(o);
                best_new = best_new.min(n);
            }
            println!("round {round}: old {o:.3}s  new {n:.3}s");
        }
        assert_eq!(so, sn);
        println!("best old {best_old:.3}s  best new {best_new:.3}s  ratio new/old {:.3}", best_new / best_old);
    }
}

