use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

/// What the lexer expects next. Each token kind has its own method; `Tokens::next` picks one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: a timestamp, a key, a word or an error comes next.
    Between,
    /// Right after a `=`: a value comes next, and it may be empty.
    AfterEquals,
    /// The line is finished, or an error was returned.
    Done,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens {
            src,
            pos: 0,
            state: State::Between,
        }
    }

    fn skip_blanks(&mut self) {
        let bytes = self.src.as_bytes();
        while self.pos < bytes.len() && is_blank(bytes[self.pos]) {
            self.pos += 1;
        }
    }

    /// Lexes the token at `self.pos`, which is neither blank nor past the end.
    fn lex_token(&mut self) -> Result<Token<'a>, LexError> {
        let pos = self.pos;
        match self.src.as_bytes()[pos] {
            b'[' => self.lex_timestamp(),
            b'"' => Err(LexError::UnexpectedQuote { pos }),
            b'=' => Err(LexError::EmptyKey { pos }),
            _ => self.lex_key_or_word(),
        }
    }

    /// `[text]`, which must be followed by a blank or the end of the line.
    fn lex_timestamp(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let open = self.pos;
        let text_start = open + 1;
        let mut close = text_start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
                Some(_) => close += 1,
            }
        }
        expect_separator(bytes, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&src[text_start..close]))
    }

    /// `key=`, which switches to `AfterEquals`, or a word running up to the next blank.
    fn lex_key_or_word(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = self.pos;
        let end = scan_unquoted(bytes, start, |byte| is_blank(byte) || byte == b'=')?;
        if bytes.get(end) == Some(&b'=') {
            self.pos = end + 1;
            self.state = State::AfterEquals;
            Ok(Token::Key(&src[start..end]))
        } else {
            self.pos = end;
            Ok(Token::Word(&src[start..end]))
        }
    }

    /// The value after `=`: quoted, bare, or empty when a blank or the end of the line follows.
    fn lex_value(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = self.pos;
        self.state = State::Between;
        match bytes.get(start) {
            None => Ok(Token::Bare("")),
            Some(&byte) if is_blank(byte) => Ok(Token::Bare("")),
            Some(b'"') => self.lex_quoted(),
            Some(_) => {
                let end = scan_unquoted(bytes, start, is_blank)?;
                self.pos = end;
                Ok(Token::Bare(&src[start..end]))
            }
        }
    }

    /// `"text"`. Only `\"`, `\\`, `\n` and `\t` may be escaped; the escapes stay in the token.
    fn lex_quoted(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let open = self.pos;
        let text_start = open + 1;
        let mut close = text_start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\') => match bytes.get(close + 1) {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => close += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: close }),
                },
                Some(_) => close += 1,
            }
        }
        expect_separator(bytes, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Quoted(&src[text_start..close]))
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = match self.state {
            State::Between => {
                self.skip_blanks();
                if self.pos >= self.src.len() {
                    return None;
                }
                self.lex_token()
            }
            State::AfterEquals => self.lex_value(),
            State::Done => return None,
        };
        if result.is_err() {
            self.state = State::Done;
        }
        Some(result)
    }
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

/// Scans unquoted text from `from` up to the first byte that satisfies `is_stop`, or the end of
/// the line. A double quote inside unquoted text is an error.
fn scan_unquoted(
    bytes: &[u8],
    from: usize,
    is_stop: impl Fn(u8) -> bool,
) -> Result<usize, LexError> {
    let mut end = from;
    while let Some(&byte) = bytes.get(end) {
        if is_stop(byte) {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos: end });
        }
        end += 1;
    }
    Ok(end)
}

/// Checks that the byte at `at`, if any, is a blank.
fn expect_separator(bytes: &[u8], at: usize) -> Result<(), LexError> {
    match bytes.get(at) {
        Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos: at }),
        _ => Ok(()),
    }
}

